import{c as a,Q as t,j as n,m as i}from"./chunks/framework.BXc4yaFE.js";const d=JSON.parse('{"title":"ChatDev: Communicative Agents for Software Development","description":"","frontmatter":{"url":"https://arxiv.org/abs/2307.07924","title":"ChatDev: Communicative Agents for Software Development","archived_date":"2026-06-09T00:00:00.000Z","arxiv_id":2307.07924,"authors":["Chen Qian","Wei Liu","Hongzhang Liu","Nuo Chen","Yufan Dang","Jiahao Li","Cheng Yang","Weize Chen","Yusheng Su","Xin Cong","Juyuan Xu","Dahai Li","Zhiyuan Liu","Maosong Sun"],"domains":["cs.SE","cs.CL","cs.AI"],"pdf_path":"pdfs/2307.07924.pdf","published_date":"2023-07-16T00:00:00.000Z","tags":["multi-agent","software-development","communicative-agents","chat-chain","llm"],"venue":"ACL 2024"},"headers":[],"relativePath":"research/papers/2023-07-16-chatdev-communicative-agents-software-development-2307-07924.md","filePath":"research/papers/2023-07-16-chatdev-communicative-agents-software-development-2307-07924.md","lastUpdated":1785909234000}'),o={name:"research/papers/2023-07-16-chatdev-communicative-agents-software-development-2307-07924.md"};function r(s,e,l,c,h,m){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="chatdev-communicative-agents-for-software-development" tabindex="-1">ChatDev: Communicative Agents for Software Development <a class="header-anchor" href="#chatdev-communicative-agents-for-software-development" aria-label="Permalink to &quot;ChatDev: Communicative Agents for Software Development&quot;">​</a></h1><p><strong>arXiv</strong>: 2307.07924 | <strong>發表</strong>: 2023-07-16 | <strong>PDF</strong>: 2023-07-16-chatdev-communicative-agents-software-development-2307-07924.pdf</p><h2 id="核心貢獻" tabindex="-1">核心貢獻 <a class="header-anchor" href="#核心貢獻" aria-label="Permalink to &quot;核心貢獻&quot;">​</a></h2><p>以「虛擬軟體公司」為比喻，採用 waterfall 模型分階段（設計→編碼→測試→文件）讓多個 LLM agent 以自然語言和程式語言交互協作。核心創新：<strong>Chat Chain</strong>（控制通訊順序）+ <strong>Communicative Dehallucination</strong>（雙 agent 對話中主動偵測並消除幻覺輸出）。發表於 ACL 2024。</p><h2 id="方法-架構" tabindex="-1">方法 / 架構 <a class="header-anchor" href="#方法-架構" aria-label="Permalink to &quot;方法 / 架構&quot;">​</a></h2><ul><li><strong>Chat Chain</strong>：將開發流程切割成有序的雙人對話原子操作（atomic chat），每步一個 instructor + 一個 assistant</li><li><strong>Communicative Dehallucination</strong>：當 assistant 給出不確定或錯誤陳述時，instructor 觸發澄清追問，迭代消除幻覺</li><li><strong>角色</strong>：CEO、CTO、Programmer、Reviewer、Tester；角色間不跨越溝通，只在相鄰階段對話</li><li><strong>語言雙軌</strong>：設計/需求用自然語言；debug/code review 用程式語言，語言選擇由上下文決定</li></ul><h2 id="關鍵發現與數據" tabindex="-1">關鍵發現與數據 <a class="header-anchor" href="#關鍵發現與數據" aria-label="Permalink to &quot;關鍵發現與數據&quot;">​</a></h2><ul><li>可成功生成可執行完整程式（vs. 早期 GPT-4 單 agent 方法高失敗率）</li><li>Communicative Dehallucination 顯著降低程式碼 logic error 率（具體數字見全文 §5）</li><li>對比實驗：純 Chat Chain（無 dehallucination）vs 完整 ChatDev，後者 code executability 提升明顯</li><li>Token 效率：248.9 tokens/loc（MetaGPT 論文反向引用此數作基準對比）</li></ul><h2 id="對-agent-team-設計的啟示" tabindex="-1">對 agent-team 設計的啟示 <a class="header-anchor" href="#對-agent-team-設計的啟示" aria-label="Permalink to &quot;對 agent-team 設計的啟示&quot;">​</a></h2><ol><li><strong>waterfall 的 staged pipeline 降低協作複雜度</strong>：每階段只需一對 agent 對話，避免全 agent 廣播混亂</li><li><strong>Communicative Dehallucination 是 multi-agent 特有的校正機制</strong>：單 agent 無法自我觸發追問，雙 agent 角色差異讓幻覺可見</li><li><strong>語言切換作為信號</strong>：程式語言溝通本身即測試，NL 交互作為設計驗收，善用媒介差異</li></ol><h2 id="原文關鍵引用-≤150字" tabindex="-1">原文關鍵引用（≤150字） <a class="header-anchor" href="#原文關鍵引用-≤150字" aria-label="Permalink to &quot;原文關鍵引用（≤150字）&quot;">​</a></h2><blockquote><p>&quot;We present ChatDev, a chat-powered software development framework in which specialized agents driven by large language models (LLMs) are guided in what to communicate (via chat chain) and how to communicate (via communicative dehallucination)... These agents actively contribute to the design, coding, and testing phases through unified language-based communication, with solutions derived from their multi-turn dialogues.&quot;</p></blockquote>',12)])])}const g=a(o,[["render",r]]);export{d as __pageData,g as default};
